mapper.update:
UPDATE datasets
SET name = #{name},
    description = #{description,jdbcType=VARCHAR},
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND deleted_at IS NULL

UPDATE datasets
SET current_version_id = #{currentVersionId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler},
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND deleted_at IS NULL

UPDATE datasets
SET deleted_at = #{deletedAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler},
    updated_at = #{updatedAt,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND deleted_at IS NULL

mapper.delete:
DELETE FROM datasets
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}
  AND NOT EXISTS (
      SELECT 1
      FROM dataset_versions
      WHERE dataset_id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  )
